  Lemma poison_walk2L : forall (x13 : word), addr + size <= ALOWSH_LO ->
    evt asegs (poison_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 lo addr size v)
